(() => {
 const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const kinds={coordination:'Koordinasi keluarga',tea:'Cinciu / teapai',photo:'Foto keluarga'},states={planned:'Terjadwal',ready:'Siap dipanggil',active:'Sedang berlangsung',done:'Selesai',cancelled:'Dibatalkan'};
 let context,records,view='journey',event='reception',query='',filter='all',taskFilter='all',request=0;
 const name=i=>window.weddingDisplayName?.(i,'id')||i.guestName;
 const eventTitle=()=>context.data.events.find(e=>e.id===event)?.title||event;
 const options=(items,selected)=>Object.entries(items).map(([id,label])=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(label)}</option>`).join('');
 const time=s=>s?new Intl.DateTimeFormat('id-ID',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Jakarta'}).format(new Date(s)):'Belum dijadwalkan';
 const linkedIds=t=>Array.isArray(t.invitationIds)?t.invitationIds:(t.invitation_id?[t.invitation_id]:[]);
 const linkedGuests=t=>linkedIds(t).map(key=>context.data.invitations.find(i=>i.id===key)).filter(Boolean);
 const attendance=key=>records.attendance.find(a=>a.subject_key===key&&a.event_id===event)||{checked_in:0,seated:0,souvenirs:0,note:'',revision:0};
 function guests(){return [...context.data.invitations.filter(i=>i.active&&i.eventIds.includes(event)).map(i=>({key:'invitation:'+i.id,name:name(i),capacity:i.seats,inv:i,rsvp:context.data.responses.find(r=>r.invitation_id===i.id&&r.event_id===event)})),...(event==='celebration'?records.general.map(g=>{const rsvp=g.responses.find(r=>r.event_id===event);return {key:g.key,name:g.name,capacity:Math.max(1,rsvp?.guest_count||1),rsvp};}):[])];}
 async function load(next,ctx){context=ctx;view=next;const current=++request;const root=$('#'+view+'-page');if(!root.dataset.loaded)root.innerHTML='<p class="journey-loading" role="status">Memuat meja kerja acara…</p>';try{const result=await ctx.api('journey');if(current!==request)return;records=result;root.dataset.loaded='true';render();}catch(error){if(current===request)root.innerHTML=`<p class="error-banner" role="alert">${esc(error.message)}</p><button class="secondary" data-j-reload>Coba lagi</button>`;}}
 function heading(title,description){return `<div class="page-heading"><div><span class="eyebrow">THE WEDDING OPERATIONS DESK</span><h1>${title}</h1><p>${description}</p></div><button class="secondary" data-j-reload>↻ Perbarui</button></div><div class="journey-flow"><span>01 · Kedatangan</span><span>02 · Seating</span><span>03 · Keluarga & teapai</span><span>04 · Foto keluarga</span><span>05 · Souvenir</span></div><p id="journey-error" class="form-error" role="alert"></p><div class="toolbar journey-filter"><label>Acara<select id="journey-event">${options(Object.fromEntries(context.data.events.map(e=>[e.id,e.title])),event)}</select></label></div>`;}
 function render(){if(!context.data.events.some(e=>e.id===event))event=context.data.events[0].id;const root=$('#'+view+'-page');root.innerHTML=view==='journey'?renderDesk():renderRundown();}
 function renderDesk(){
  const allGuests=guests(),list=allGuests.filter(g=>g.rsvp?.status!=='declined'||attendance(g.key).checked_in>0),sum=field=>list.reduce((n,g)=>n+attendance(g.key)[field],0),checked=sum('checked_in'),seated=sum('seated'),souvenirs=sum('souvenirs'),stock=records.stock[event],planned=list.reduce((n,g)=>n+g.capacity,0),expected=list.reduce((n,g)=>n+(g.rsvp?.status==='attending'?g.rsvp.guest_count:0),0);
  const filtered=(filter==='declined'?allGuests.filter(g=>g.rsvp?.status==='declined'):list).filter(g=>{const a=attendance(g.key);return g.name.toLocaleLowerCase('id-ID').includes(query.toLocaleLowerCase('id-ID'))&&(filter==='all'||filter==='declined'||filter==='waiting'&&!a.checked_in||filter==='arrived'&&a.checked_in>0||filter==='souvenir'&&a.checked_in>a.souvenirs);});
  return heading('Check-in & <em>souvenir.</em>','Cari nama tamu, catat jumlah yang benar-benar tiba, lalu arahkan ke meja dan serahkan souvenir.')+`<div class="stats"><article><span>Alokasi / perkiraan maksimum</span><strong>${planned}</strong><small>${expected} orang RSVP hadir · ${list.length} undangan / tamu umum</small></article><article><span>Sudah check-in</span><strong>${checked}</strong><small>${seated} sudah duduk · ${checked-seated} perlu diarahkan</small></article><article><span>Souvenir diserahkan</span><strong>${souvenirs}</strong><small>${checked-souvenirs} tamu hadir belum menerima</small></article><article><span>Sisa persediaan souvenir</span><strong>${stock?stock-souvenirs:'—'}</strong><small>${stock?'dari '+stock+' souvenir':'Isi stok untuk memantau persediaan'}</small></article></div>${stock&&souvenirs>=stock?'<p class="error-banner">Persediaan souvenir habis atau jumlah yang diserahkan melebihi stok. Periksa pencatatan dan persediaan fisik.</p>':''}<div class="panel"><div class="toolbar"><label class="search-label">Cari tamu<input id="journey-search" type="search" value="${esc(query)}" placeholder="Nama pada undangan atau RSVP umum"></label><label>Status<select id="journey-filter">${options({all:'Semua tamu',waiting:'Belum tiba',arrived:'Sudah tiba',souvenir:'Belum menerima semua souvenir',declined:'Tidak hadir (arsip)'},filter)}</select></label><button class="quiet" data-j-stock>Atur stok</button><button class="quiet" data-j-export>Unduh daftar CSV</button></div><div class="table-wrap"><table><thead><tr><th>Tamu / RSVP</th><th>Alokasi</th><th>Check-in</th><th>Meja / duduk</th><th>Souvenir</th><th>Tindakan</th></tr></thead><tbody>${filtered.map(g=>{const a=attendance(g.key);return `<tr><td><strong>${esc(g.name)}</strong><small>${g.inv?'Undangan personal':'RSVP umum'} · ${g.rsvp?.status==='attending'?'RSVP hadir '+g.rsvp.guest_count:g.rsvp?.status==='declined'?'RSVP tidak hadir':'Belum RSVP'}</small></td><td>${g.capacity} orang</td><td><span class="pill ${a.checked_in?'good':''}">${a.checked_in} tiba</span></td><td>${esc((g.rsvp?.status==='declined'?'Arsip · meja tidak aktif':g.inv?.receptionTable?.replace('-',' · Meja '))||(event==='reception'?'Belum ditentukan':'Tempat bebas'))}<small>${a.seated} sudah duduk</small></td><td>${a.souvenirs} diserahkan</td><td><button class="secondary" data-j-guest="${esc(g.key)}">${a.checked_in?'Perbarui':'Check-in'}</button></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">Tidak ada tamu yang cocok.</td></tr>'}</tbody></table></div></div><p class="data-note">Jumlah tersimpan sebagai total per undangan dan acara. Gunakan jumlah aktual, bukan otomatis seluruh kursi. RSVP tetap terpisah. Souvenir dibatasi sebanyak tamu yang sudah check-in; nomor meja menggunakan alokasi CMS yang sama.</p>`+renderActivity();
 }
 function renderActivity(){const rows=records.activity.filter(a=>a.event_id===event).slice(0,12);return `<details class="panel journey-log"><summary>Aktivitas petugas terakhir</summary>${rows.length?rows.map(a=>{const guest=guests().find(g=>g.key===a.subject_key),task=records.tasks.find(t=>'task:'+t.id===a.subject_key);let v;try{v=JSON.parse(a.after_value);}catch{v={};}return `<p><strong>${esc(guest?.name||task?.family_name||'Catatan acara')}</strong> · ${a.action==='attendance'?`${v.checkedIn} tiba, ${v.seated} duduk, ${v.souvenirs} souvenir`:a.action==='seating'?'Meja '+esc(v||'dikosongkan'):esc(states[v.status]||'Agenda diubah')}<small>${esc(time(a.created_at))} · ${esc(a.actor)}</small></p>`;}).join(''):'<p>Belum ada aktivitas untuk acara ini.</p>'}</details>`;}
 function renderRundown(){const tasks=records.tasks.filter(t=>t.event_id===event&&t.status!=='cancelled'),visible=records.tasks.filter(t=>t.event_id===event&&(taskFilter==='all'||t.kind===taskFilter));return heading('Keluarga & <em>rundown.</em>','Satu daftar panggilan untuk keluarga, petugas, cinciu/teapai, dan sesi foto. Jadwal memakai waktu WIB.')+`<div class="stats">${[['Keluarga / koordinasi',tasks.filter(t=>t.kind==='coordination').length],['Teapai selesai',tasks.filter(t=>t.kind==='tea'&&t.status==='done').length],['Foto keluarga selesai',tasks.filter(t=>t.kind==='photo'&&t.status==='done').length],['Siap dipanggil',tasks.filter(t=>t.status==='ready').length]].map(([label,n])=>`<article><span>${label}</span><strong>${n}</strong><small>${tasks.filter(t=>t.status==='active').length} agenda sedang berlangsung</small></article>`).join('')}</div><div class="panel"><div class="toolbar"><label>Tahap<select id="journey-task-filter">${options({all:'Semua tahap',...kinds},taskFilter)}</select></label><button class="primary" data-j-task="new">+ Tambah agenda keluarga</button><button class="quiet" data-j-template>Susun contoh alur</button><button class="quiet" data-j-export>Unduh rundown CSV</button></div><div class="journey-rundown">${visible.map(t=>`<article class="journey-task ${t.status==='active'?'is-active':''}"><span class="journey-order">${t.position}</span><div><span class="eyebrow">${esc(kinds[t.kind])}</span><h2>${esc(t.family_name)}</h2><p>${esc(t.members||'Isi anggota keluarga yang perlu dipanggil.')}</p><p><strong>${esc(time(t.scheduled_at))}</strong> · ${esc(t.location||'Lokasi belum ditentukan')}</p><p>Petugas: ${esc(t.assignee||'Belum ditugaskan')}${t.contact?' · '+esc(t.contact):''}</p>${linkedIds(t).length?`<div class="journey-linked-summary"><strong>${linkedIds(t).length} undangan ditautkan · ${linkedGuests(t).reduce((n,i)=>n+i.seats,0)} alokasi tamu · ${records.attendance.filter(a=>linkedIds(t).includes(a.invitation_id)&&a.event_id===event).reduce((n,a)=>n+a.checked_in,0)} sudah check-in</strong><ul>${linkedGuests(t).map(i=>`<li>${esc(name(i))} · ${records.attendance.find(a=>a.invitation_id===i.id&&a.event_id===event)?.checked_in||0}/${i.seats} tiba</li>`).join('')}</ul></div>`:''}${t.note?`<p class="journey-note">${esc(t.note)}</p>`:''}</div><div class="journey-task-actions"><span class="pill ${t.status==='done'?'good':t.status==='active'?'warm':''}">${esc(states[t.status])}</span><button class="secondary" data-j-task="${t.id}">Atur / ubah status</button></div></article>`).join('')||'<p class="empty">Mulai dengan menambahkan keluarga dan petugas, atau susun contoh alur sebagai draf.</p>'}</div></div><p class="data-note">Siapkan daftar nama dan hubungan keluarga, tentukan satu petugas pemanggil, lalu ubah status: Terjadwal → Siap dipanggil → Sedang berlangsung → Selesai. Foto keluarga sebaiknya memprioritaskan orang tua dan lansia. Jadwal cinciu/teapai dikonfirmasi dengan kedua keluarga sebelum dipakai. Catatan ini untuk koordinasi internal CMS.</p>`+renderActivity();}
 function dialog(title,content,onSubmit){$('#journey-dialog')?.remove();const d=document.createElement('dialog');d.id='journey-dialog';d.innerHTML=`<form id="journey-form"><div class="dialog-heading"><h2>${title}</h2><button class="icon-button" type="button" data-j-close aria-label="Tutup">×</button></div>${content}<p id="journey-dialog-error" class="form-error" role="alert"></p><div class="dialog-actions"><button class="secondary" type="button" data-j-close>Batal</button><button class="primary" type="submit">Simpan</button></div></form>`;document.body.append(d);d.querySelectorAll('[data-j-close]').forEach(b=>b.onclick=()=>d.close());d.onclose=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=d.querySelector('[type=submit]');b.disabled=true;try{await onSubmit(new FormData(e.target));d.close();context.toast('Catatan acara tersimpan.');await context.refresh();}catch(error){$('#journey-dialog-error').textContent=error.message;}finally{b.disabled=false;}};d.showModal();}
 function guestDialog(key){const g=guests().find(g=>g.key===key);if(!g)return;const a=attendance(key),tables={'':'Belum ditentukan'};for(const [group,n] of Object.entries({Galilea:5,Jordan:10,Pishon:10}))for(let i=1;i<=n;i++)tables[group+'-'+i]=group+' · Meja '+i;
  dialog(esc(g.name),`<p>${esc(eventTitle())} · maksimum ${g.capacity} orang</p>${g.rsvp?.status==='declined'?'<p class="error-banner">Tamu sebelumnya memilih tidak hadir. Pastikan jumlah aktual saat check-in.</p>':''}<div class="form-columns"><label>Total orang sudah tiba<input name="checkedIn" type="number" min="0" max="${g.capacity}" value="${a.checked_in}" required></label><label>Total orang sudah duduk<input name="seated" type="number" min="0" max="${g.capacity}" value="${a.seated}" required></label><label>Total souvenir diserahkan<input name="souvenirs" type="number" min="0" max="${g.capacity}" value="${a.souvenirs}" required></label></div>${g.inv&&event==='reception'?`<label>Meja Resepsi I<select name="table">${options(tables,g.inv.receptionTable||'')}</select><small>Alokasi maksimum 10 kursi per meja. Perubahan meja berlaku juga di undangan tamu.</small></label>`:''}<label>Catatan kedatangan<textarea name="note" maxlength="500">${esc(a.note)}</textarea></label><p class="data-note">Jika baru sebagian rombongan tiba, isi jumlah tersebut. Simpan ulang total untuk menambah kedatangan berikutnya atau mengoreksi catatan.</p>`,async f=>{if(g.inv&&event==='reception'&&f.get('table')!==(g.inv.receptionTable||''))await context.api('journey/seating',{method:'PUT',body:{invitationId:g.inv.id,table:f.get('table')}});await context.api('journey/attendance',{method:'PUT',body:{key:g.key,eventId:event,checkedIn:Number(f.get('checkedIn')),seated:Number(f.get('seated')),souvenirs:Number(f.get('souvenirs')),note:f.get('note'),revision:a.revision}});});
 }
 function taskDialog(taskId){const t=records.tasks.find(t=>t.id===taskId)||{kind:'coordination',family_name:'',members:'',assignee:'',contact:'',scheduled_at:'',position:records.tasks.filter(t=>t.event_id===event).length+1,status:'planned',location:'',note:'',revision:0};const invites=context.data.invitations.filter(i=>i.eventIds.includes(event)&&(i.active||linkedIds(t).includes(i.id)));const selected=new Set(linkedIds(t));dialog(t.id?'Atur agenda keluarga':'Tambah agenda keluarga',`<p>${esc(eventTitle())}</p><label>Keluarga / nama sesi<input name="familyName" maxlength="100" value="${esc(t.family_name)}" placeholder="Keluarga mempelai wanita" required></label><div class="form-columns"><label>Tahap<select name="kind">${options(kinds,t.kind)}</select></label><label>Urutan panggilan<input name="position" type="number" min="1" max="999" value="${t.position}" required></label></div><label>Nama anggota & hubungan keluarga<textarea name="members" maxlength="1000" placeholder="Orang tua, saudara kandung, keluarga besar…">${esc(t.members)}</textarea></label><fieldset class="journey-invites"><legend>Tautkan undangan</legend><p>Pilih beberapa undangan untuk keluarga atau sesi yang sama.</p><label>Cari undangan<input type="search" id="journey-invite-search" placeholder="Cari nama tamu"></label><p id="journey-selected-count" role="status">${selected.size} undangan dipilih</p><div class="journey-invite-options">${invites.map(i=>`<label class="checkbox-row journey-invite-option" data-invite-name="${esc(name(i).toLocaleLowerCase('id-ID'))}"><input type="checkbox" name="invitationIds" value="${i.id}" ${selected.has(i.id)?'checked':''}><span>${esc(name(i))}<small>${i.seats} tamu${i.active?'':' · Nonaktif, hapus pilihan sebelum menyimpan'}</small></span></label>`).join('')||'<p>Belum ada undangan untuk acara ini.</p>'}</div></fieldset><div class="form-columns"><label>Petugas penanggung jawab<input name="assignee" maxlength="100" value="${esc(t.assignee)}"></label><label>Kontak petugas<input name="contact" maxlength="50" value="${esc(t.contact)}"></label><label>Jadwal WIB<input name="scheduled" type="datetime-local" value="${esc(t.scheduled_at.slice(0,16))}"></label><label>Status<select name="status">${options(states,t.status)}</select></label></div><label>Lokasi / titik berkumpul<input name="location" maxlength="200" value="${esc(t.location)}"></label><label>Instruksi untuk petugas<textarea name="note" maxlength="1000">${esc(t.note)}</textarea></label>`,f=>context.api('journey/tasks'+(t.id?'/'+t.id:''),{method:t.id?'PUT':'POST',body:{eventId:event,kind:f.get('kind'),familyName:f.get('familyName'),members:f.get('members'),invitationIds:f.getAll('invitationIds'),assignee:f.get('assignee'),contact:f.get('contact'),scheduledAt:f.get('scheduled')?f.get('scheduled')+':00+07:00':'',position:Number(f.get('position')),status:f.get('status'),location:f.get('location'),note:f.get('note'),revision:t.revision}}));}
 function stockDialog(){dialog('Persediaan souvenir',`<p>Isi jumlah awal untuk setiap acara. Nilai 0 berarti stok belum ditentukan.</p>${context.data.events.map(e=>`<label>${esc(e.title)}<input type="number" name="${e.id}" min="0" max="100000" value="${records.stock[e.id]}" required></label>`).join('')}`,f=>context.api('journey/stock',{method:'PUT',body:Object.fromEntries(context.data.events.map(e=>[e.id,Number(f.get(e.id))]))}));}
 function templateDialog(){dialog('Susun draf alur keluarga',`<p>Tambahkan empat agenda untuk ${esc(eventTitle())}. Isi nama anggota, petugas, dan waktu setelah berkoordinasi dengan keluarga.</p><ol><li>Briefing dan titik kumpul keluarga</li><li>Cinciu / teapai dengan orang tua dan sesepuh</li><li>Foto orang tua dan keluarga inti</li><li>Foto keluarga besar</li></ol><p class="data-note">Agenda dibuat tanpa jam pasti; sesuaikan dengan rundown acara. Sesi teapai dapat dibatalkan bila dilakukan pada hari atau tempat lain.</p>`,async()=>{const offset=Math.max(0,...records.tasks.filter(t=>t.event_id===event).map(t=>t.position));for(const [i,[kind,familyName,note]] of [['coordination','Briefing keluarga & titik kumpul','Petugas memeriksa anggota keluarga, akses lansia, dan urutan panggilan.'],['tea','Cinciu / teapai · orang tua & sesepuh','Konfirmasi urutan dengan keluarga; siapkan teh, cangkir, tempat duduk, dan pendamping.'],['photo','Foto orang tua & keluarga inti','Prioritaskan orang tua dan lansia. Petugas pemanggil memastikan semua anggota hadir.'],['photo','Foto keluarga besar','Gunakan daftar kelompok; panggil kelompok berikutnya sebelum sesi sebelumnya selesai.']].entries())await context.api('journey/tasks',{method:'POST',body:{eventId:event,kind,familyName,note,members:'',invitationId:'',assignee:'',contact:'',scheduledAt:'',position:offset+i+1,status:'planned',location:'',revision:0}});});}
 function exportCsv(){const rows=view==='journey'?[['Nama','Acara','Alokasi','RSVP','Check-in','Meja','Sudah duduk','Souvenir','Catatan'],...guests().filter(g=>filter==='declined'?g.rsvp?.status==='declined':g.rsvp?.status!=='declined'||attendance(g.key).checked_in>0).map(g=>{const a=attendance(g.key);return [g.name,eventTitle(),g.capacity,g.rsvp?.status||'pending',a.checked_in,g.rsvp?.status==='declined'?'':g.inv?.receptionTable||'',a.seated,a.souvenirs,a.note];})]:[['Urutan','Acara','Tahap','Keluarga','Anggota','Undangan ditautkan','Petugas','Kontak','Jadwal WIB','Lokasi','Status','Catatan'],...records.tasks.filter(t=>t.event_id===event).map(t=>[t.position,eventTitle(),kinds[t.kind],t.family_name,t.members,linkedGuests(t).map(name).join(' | '),t.assignee,t.contact,t.scheduled_at,t.location,states[t.status],t.note])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`wedding-${view}-${event}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-j-reload],[data-j-guest],[data-j-task],[data-j-stock],[data-j-template],[data-j-export]');if(!b)return;if(b.hasAttribute('data-j-reload'))context.refresh().catch(error=>context.toast(error.message));else if(b.dataset.jGuest)guestDialog(b.dataset.jGuest);else if(b.dataset.jTask)taskDialog(b.dataset.jTask);else if(b.hasAttribute('data-j-stock'))stockDialog();else if(b.hasAttribute('data-j-template'))templateDialog();else exportCsv();});
 document.addEventListener('change',e=>{if(e.target.name==='invitationIds')$('#journey-selected-count').textContent=document.querySelectorAll('#journey-dialog input[name=invitationIds]:checked').length+' undangan dipilih';if(e.target.id==='journey-event'){event=e.target.value;query='';render();}if(e.target.id==='journey-filter'){filter=e.target.value;render();}if(e.target.id==='journey-task-filter'){taskFilter=e.target.value;render();}});
 document.addEventListener('input',e=>{if(e.target.id==='journey-invite-search'){const search=e.target.value.trim().toLocaleLowerCase('id-ID');document.querySelectorAll('.journey-invite-option').forEach(label=>label.hidden=!label.dataset.inviteName.includes(search));}if(e.target.id==='journey-search'){query=e.target.value;const start=e.target.selectionStart;render();$('#journey-search').focus();$('#journey-search').setSelectionRange(start,start);}});
 window.weddingJourney={load};
})();
